/* Redis SDS 结构定义（sdshdr8 为例） */
struct __attribute__ ((__packed__)) sdshdr8 {
    uint8_t len;        /* 已使用长度 */
    uint8_t alloc;      /* 分配总长度（不含头部和 '\0'） */
    unsigned char flags; /* 低 3 位标识类型：SDS_TYPE_8 */
    char buf[];          /* 柔性数组，实际数据存储区 */
};

/* 对比 C 字符串 */
// C: char *s = "hello";  strlen(s) = O(N)
// SDS: sds s = sdsnew("hello");  sdslen(s) = O(1)
